) AS v(id, uid, tier_id, start_time, end_time, created_at, is_active, deleted_at, payment_order_id)
WHERE EXISTS (SELECT 1 FROM historical_schema."user" u WHERE u.uid = v.uid::uuid)
  AND EXISTS (SELECT 1 FROM historical_schema.tier t WHERE t.tier_id = v.tier_id::uuid)
  AND NOT EXISTS (SELECT 1 FROM historical_schema.user_tier ut WHERE ut.id = v.id::uuid)
ON CONFLICT DO NOTHING;

-- 6. Insert historical_context_rows.sql
INSERT INTO historical_schema.historical_context ("context_id", "created_by", "name", "description", "era", "category", "year", "start_year", "end_year", "is_bc", "location", "image_url", "video_url", "is_published", "created_at", "updated_at", "deleted_at")
SELECT
    v.context_id::uuid,
    v.created_by::uuid,
    v.name,
    v.description,
    v.era,
    v.category,
    v.year::integer,
    v.start_year::integer,
    v.end_year::integer,
    v.is_bc::boolean,
    v.location,
    v.image_url,
    v.video_url,
    v.is_published::boolean,
    v.created_at::timestamp,
    v.updated_at::timestamp,
    v.deleted_at::timestamp
FROM (VALUES
('1055f5d5-7249-46c9-a5c9-84508e09a9eb', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Như Nguyệt', 'Trận chiến phòng ngự chiến lược trên sông Như Nguyệt, nơi quân dân nhà Lý chặn đứng và đánh bại cuộc xâm lược của quân Tống.', 'MEDIEVAL', null, 1077, null, null, false, 'Sông Như Nguyệt (sông Cầu), Bắc Ninh', 'https://lh3.googleusercontent.com/u/0/d/1ZghcNjvUn1ggKEOjsMrdtJQTsbhDselY', 'https://www.youtube.com/watch?v=tqt79qt7orA', true, '2026-06-05 03:08:31.960434', '2026-06-05 03:19:12.264045', null), ('3870c36d-2dfe-4298-9acd-a8548feb89f8', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Đông Bộ Đầu', 'Trận phản công chiến lược của quân dân nhà Trần tại bến Đông Bộ Đầu, đánh bại đạo quân Mông Cổ xâm lược lần thứ nhất.', 'MEDIEVAL', null, 1258, null, null, false, 'Bến Đông Bộ Đầu (sông Hồng), Hà Nội', 'https://lh3.googleusercontent.com/u/0/d/16ofn6Wtef0SDuViCmMyIq4f4lGjN3hLl', 'https://www.youtube.com/watch?v=esY5SfGnkiI', true, '2026-06-05 05:01:23.844087', '2026-06-05 05:21:43.606205', null), ('389ffbf2-0f19-4478-96e2-9a36f17d25b3', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Điện Biên Phủ trên không', 'Chiến dịch phòng không quy mô lớn đánh bại cuộc tập kích chiến lược bằng B-52 của đế quốc Mỹ vào Hà Nội, Hải Phòng, buộc Mỹ ký Hiệp định Paris.', 'CONTEMPORARY', null, 1972, null, null, false, 'Bầu trời Hà Nội, Hải Phòng và các tỉnh miền Bắc', 'https://lh3.googleusercontent.com/u/0/d/1XSk_vLfmMXNf45GqiFC7YP-Ec-yDxQtI', 'https://www.youtube.com/watch?v=B_h556DlLmw', true, '2026-06-05 05:42:38.842465', '2026-06-05 05:42:38.842482', null), ('a9d5bce8-bee8-4044-b361-5f7517dfacc3', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Rạch Gầm - Xoài Mút', 'Trận thủy chiến chớp nhoáng tiêu diệt liên quân Xiêm - Nguyễn, bảo vệ vững chắc chủ quyền lãnh thổ phía Nam.', 'MODERN', null, 1785, null, null, false, 'Sông Tiền (đoạn Rạch Gầm - Xoài Mút), Tiền Giang', 'https://lh3.googleusercontent.com/u/0/d/1O3dEoQKsV-8AeN564aNjjAWVlUIzFjrn', 'https://www.youtube.com/watch?v=kOjHLK7u5Ho', true, '2026-06-05 05:30:07.457324', '2026-06-05 05:31:24.87779', null), ('c06a4c2e-5549-4010-9475-2b19ec6fa1ef', '687b57fe-865c-496a-83b3-f83690885dd1', 'Chiến dịch Điện Biên Phủ', 'Chiến dịch bao vây, tiến công tiêu diệt tập đoàn cứ điểm Điện Biên Phủ, kết thúc thắng lợi cuộc kháng chiến chống thực dân Pháp.', 'CONTEMPORARY', null, 1954, null, null, false, 'Lòng chảo Điện Biên Phủ, tỉnh Điện Biên', 'https://lh3.googleusercontent.com/u/0/d/1tnaYjVPI8yWLa5ML6noVboZ3Pc4ykucU', 'https://www.youtube.com/watch?v=CD8sKixEDsI', true, '2026-06-05 05:38:51.22387', '2026-06-05 05:38:51.223888', null), ('d99b373f-dde4-49e8-8c93-1f31d6e8b5e7', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Bạch Đằng 938', 'Trận chiến năm 938 nơi Ngô Quyền đánh bại quân Nam Hán trên sông Bạch Đằng bằng chiến thuật cọc gỗ dưới lòng sông, mở ra thời kỳ độc lập lâu dài cho Việt Nam.', 'MEDIEVAL', 'WAR', 938, 938, 939, false, 'Sông Bạch Đằng, Quảng Ninh - Hải Phòng', 'https://lh3.googleusercontent.com/u/0/d/1s_ffksR_CfhD7puJkob2J1GEHEfPY9dK', 'https://www.youtube.com/watch?v=ZPIUuLtRUFY&t=4s', true, '2026-03-24 18:26:00.401582', '2026-06-06 09:59:05.493646', null), ('db4b930d-5336-410a-946a-18dd42471248', '687b57fe-865c-496a-83b3-f83690885dd1', 'Chiến dịch Hồ Chí Minh', 'Chiến dịch tiến công quy mô lớn nhất, đánh chiếm Sài Gòn, kết thúc thắng lợi cuộc kháng chiến chống Mỹ, thống nhất hoàn toàn đất nước.', 'CONTEMPORARY', null, 1975, null, null, false, 'Sài Gòn - Gia Định (TP. Hồ Chí Minh)', 'https://lh3.googleusercontent.com/u/0/d/18tSEFkuaGM_di5LTTPuxwj7b4400ka1v', 'https://www.youtube.com/watch?v=bp7JBr8D_q4', true, '2026-06-05 07:02:55.210031', '2026-06-18 06:42:56.615884', null), ('de09e246-703a-4f00-bd33-9a1fb4dbd5e5', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Bạch Đằng 1288', 'Trận thủy chiến tiêu diệt hoàn toàn hạm đội thủy quân Nguyên Mông, kết thúc thắng lợi cuộc kháng chiến chống Nguyên Mông lần thứ ba.', 'MEDIEVAL', null, 1288, null, null, false, 'Sông Bạch Đằng, Quảng Ninh - Hải Phòng', 'https://lh3.googleusercontent.com/u/0/d/1Rudrc5ocIVNfG2kGpp-gxBMb-OLgzILo', 'https://www.youtube.com/watch?v=dWOqP_OgEsI', true, '2026-06-05 05:10:15.704382', '2026-06-05 05:22:52.389229', null), ('e811b3e5-4b69-45a0-a1cd-f9f41526b3bb', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Chi Lăng - Xương Giang', 'Trận phục kích và công kiên chiến lược tiêu diệt đạo quân viện binh của nhà Minh, buộc Vương Thông phải đầu hàng, kết thúc khởi nghĩa Lam Sơn.', 'MEDIEVAL', null, 1427, null, null, false, 'Ải Chi Lăng (Lạng Sơn) và thành Xương Giang (Bắc Giang)', 'https://lh3.googleusercontent.com/u/0/d/1JtgyToxqW8k783ag7TPx5pCdduYBnaKQ', 'https://www.youtube.com/watch?v=Q_M4NwD22es', true, '2026-06-05 05:15:23.316856', '2026-06-05 05:23:33.558275', null), ('f1a45c4c-69b9-47e5-907c-ae2236a79f69', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trận Ngọc Hồi - Đống Đa', 'Chiến dịch tiến công thần tốc đánh tan 29 vạn quân Thanh xâm lược vào dịp Tết Kỷ Dậu, giải phóng Thăng Long.', 'MODERN', null, 1789, null, null, false, 'Ngọc Hồi, Đống Đa (Hà Nội)', 'https://lh3.googleusercontent.com/u/0/d/1JexJ-NfzcvOIg_SYNiyFzQAhEOw0v0pD', 'https://www.youtube.com/watch?v=TqRWvdXrQ-Y', true, '2026-06-05 05:34:48.30215', '2026-06-05 05:34:48.302168', null)
) AS v(context_id, created_by, name, description, era, category, year, start_year, end_year, is_bc, location, image_url, video_url, is_published, created_at, updated_at, deleted_at)
WHERE EXISTS (SELECT 1 FROM historical_schema."user" u WHERE u.uid = v.created_by::uuid)
  AND NOT EXISTS (SELECT 1 FROM historical_schema.historical_context c WHERE c.context_id = v.context_id::uuid OR c.name = v.name)
ON CONFLICT DO NOTHING;

-- 7. Insert character_rows.sql
INSERT INTO historical_schema.character ("character_id", "created_by", "name", "title", "background", "image_url", "personality", "is_published", "created_at", "updated_at", "deleted_at", "born_year", "born_month", "born_day", "is_born_bc", "death_year", "death_month", "death_day", "is_death_bc", "model_url")
SELECT
    v.character_id::uuid,
    v.created_by::uuid,
    v.name,
    v.title,
    v.background,
    v.image_url,
    v.personality,
    v.is_published::boolean,
    v.created_at::timestamp,
    v.updated_at::timestamp,
    v.deleted_at::timestamp,
    v.born_year::integer,
    v.born_month::integer,
    v.born_day::integer,
    v.is_born_bc::boolean,
    v.death_year::integer,
    v.death_month::integer,
    v.death_day::integer,
    v.is_death_bc::boolean,
    v.model_url
FROM (VALUES
('02685894-ee3e-40bb-9a49-0c86884c2a48', '687b57fe-865c-496a-83b3-f83690885dd1', 'Võ Nguyên Giáp', 'Đại tướng đầu tiên, Tổng Tư lệnh của Quân đội nhân dân Việt Nam', 'Đại tướng Võ Nguyên Giáp là vị Tổng tư lệnh đầu tiên của Quân đội Nhân dân Việt Nam, người chỉ huy trực tiếp làm nên chiến thắng Điện Biên Phủ chấn động địa cầu.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/vo_nguyen_giap/vo_nguyen_giap_2D.jpg', 'Điềm tĩnh, cẩn trọng, mang tư duy quân sự lỗi lạc và tấm lòng nhân văn sâu sắc với nhân dân, chiến sĩ.', true, '2026-06-05 09:49:46.570701', '2026-07-02 09:05:37.27987', null, 1911, 8, 25, false, 2013, 10, 4, false, null), ('271ad505-eb90-4a15-9b7d-e1fb1f8bf2f0', '687b57fe-865c-496a-83b3-f83690885dd1', 'Bế Văn Đàng', 'Anh hùng lực lượng Quân đội nhân dân Việt Nam', 'Bế Văn Đàn là một anh hùng lực lượng vũ trang nhân dân Việt Nam, nổi tiếng với hành động dũng cảm lấy thân mình làm giá súng trong chiến dịch Điện Biên Phủ.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Dũng cảm, kiên cường, hy sinh quên mình vì đồng đội và đất nước.', true, '2026-06-05 13:26:00.724419', '2026-06-18 06:37:51.633915', '2026-06-18 06:37:50.989263', 1931, null, null, false, 1953, 12, 12, false, null), ('55ae763f-2c8f-4918-bf31-b43566c3c355', '687b57fe-865c-496a-83b3-f83690885dd1', 'Ngô Quyền', 'Vị vua khai sáng thời kỳ độc lập', 'Ngô Quyền là người chỉ huy trận Bạch Đằng năm 938, sử dụng chiến thuật cọc gỗ dưới lòng sông để đánh bại quân Nam Hán.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Quyết đoán, hùng dũng và yêu nước.', true, '2026-03-21 13:01:16.500784', '2026-06-04 14:50:52.668009', null, 898, 3, 12, false, 944, 2, 14, false, 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_3D.glb'), ('5f1050f7-a0f7-42e2-b130-7aa843e17787', '687b57fe-865c-496a-83b3-f83690885dd1', 'Lý Thường Kiệt', 'Việt Quốc Công', 'Lý Thường Kiệt là nhà quân sự, chính trị lỗi lạc thời Lý, tác giả của bài thơ "Nam quốc sơn hà" - bản tuyên ngôn độc lập đầu tiên của Việt Nam.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ly_thuong_kiet/ly_thuong_kiet_2D.jpg', 'Kiên trung, tài trí, mang đậm tinh thần tự tôn dân tộc và tư tưởng quân sự chủ động tấn công để phòng vệ.', true, '2026-06-05 07:24:57.62968', '2026-08-02 02:44:51.484583', null, 1019, null, null, false, 1105, null, null, false, null), ('77acdd8c-c6d9-4364-8c78-9afeb2d4cd56', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trần Quốc Tuấn', 'Hưng Đạo Vương', 'Trần Hưng Đạo là nhà quân sự kiệt xuất, vị chỉ huy tối cao của quân đội nhà Trần trong hai cuộc kháng chiến chống quân Nguyên Mông.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Trung quân ái quốc, dũng lược, luôn đặt lợi ích quốc gia lên trên hiềm khích cá nhân.', true, '2026-06-05 08:04:28.721576', '2026-06-05 09:46:23.371766', null, 1228, null, null, false, 1300, 10, 3, false, null), ('b280d6b3-5507-4b87-bcc7-cbcbff8ab3b6', '687b57fe-865c-496a-83b3-f83690885dd1', 'Lê Lợi', 'Lê Thái Tổ', 'Lê Thái Tổ là người khởi xướng và lãnh đạo cuộc khởi nghĩa Lam Sơn thắng lợi, lập ra nhà Hậu Lê, mở ra thời kỳ độc lập tự chủ mới.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/le_loi/le_loi_2D.jpg', 'Cương nghị, trọng hiền tài, mang tư tưởng nhân nghĩa, lấy dân làm gốc.', true, '2026-06-05 08:15:25.111124', '2026-06-11 15:38:04.649439', null, 1385, 9, 10, false, 1433, 9, 5, false, 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/le_loi/le_loi_3D.glb'), ('b995a583-d2c1-44bd-8129-3e51b5eae371', '687b57fe-865c-496a-83b3-f83690885dd1', 'Văn Tiến Dũng', 'Đại tướng Quân đội nhân dân Việt Nam', 'Đại tướng Văn Tiến Dũng là nhà quân sự tài ba, Tư lệnh Chiến dịch Hồ Chí Minh lịch sử, có nhiều đóng góp to lớn vào sự nghiệp giải phóng dân tộc.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Sâu sát, quyết liệt, giỏi trong việc nắm bắt thời cơ và tổ chức các chiến dịch tiến công hiệp đồng binh chủng quy mô lớn.', true, '2026-06-05 13:34:08.909614', '2026-06-05 13:47:32.952878', null, 1917, 5, 2, false, 2002, 3, 17, false, null), ('c1393217-a073-4c6d-b3a7-0fcd6311a3d0', '687b57fe-865c-496a-83b3-f83690885dd1', 'Trần Thái Tông', 'hoàng đế khai quốc của nhà Trần', 'Trần Thái Tông là vị vua đầu tiên của nhà Trần, người đặt nền móng cho sự thịnh trị của vương triều và trực tiếp lãnh đạo kháng chiến chống Mông Cổ.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Anh minh, quyết đoán, có tài kinh bang tế thế và lòng mộ đạo Phật giáo sâu sắc.', true, '2026-06-05 07:52:02.290693', '2026-06-05 09:46:34.561522', null, 1218, 7, 17, false, 1277, 5, 4, false, null), ('f182b646-0e89-4fbf-bee6-47cd5cf996fb', '687b57fe-865c-496a-83b3-f83690885dd1', 'Nguyễn Huệ', 'Vua Quang Trung', 'Quang Trung - Nguyễn Huệ là thủ lĩnh phong trào Tây Sơn, nhà quân sự thiên tài với nghệ thuật hành quân thần tốc và đánh tiêu diệt.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/quang_trung/quang_trung_2D.jpg', 'Thần tốc, quyết đoán, mang tầm nhìn vượt thời đại trong cả quân sự và cải cách nội trị.', true, '2026-06-05 08:47:21.824905', '2026-08-02 02:45:11.180707', null, 1753, null, null, false, 1792, 9, 16, false, null), ('f8899221-9165-483f-99e4-0a8fccb970be', '687b57fe-865c-496a-83b3-f83690885dd1', 'Phan Đình Giót', 'Anh hùng lực lượng Quân đội nhân dân Việt Nam', 'Phan Đình Giót là một anh hùng lực lượng vũ trang nhân dân, người đã lấy thân mình lấp lỗ châu mai trong trận đánh cứ điểm Him Lam, mở màn chiến dịch Điện Biên Phủ.', 'https://rnqndhasoerjovtmxehz.supabase.co/storage/v1/object/public/character-assets/character/ngo_quyen/ngo_quyen_2D.jpg', 'Quả cảm, gan dạ, sẵn sàng hy sinh thân mình để giành chiến thắng.', true, '2026-06-05 13:31:09.819034', '2026-06-05 13:31:27.244732', null, 1922, null, null, false, 1954, 3, 13, false, null)
) AS v(character_id, created_by, name, title, background, image_url, personality, is_published, created_at, updated_at, deleted_at, born_year, born_month, born_day, is_born_bc, death_year, death_month, death_day, is_death_bc, model_url)
WHERE EXISTS (SELECT 1 FROM historical_schema."user" u WHERE u.uid = v.created_by::uuid)
  AND NOT EXISTS (SELECT 1 FROM historical_schema."character" ch WHERE ch.character_id = v.character_id::uuid)
ON CONFLICT DO NOTHING;

