  AND EXISTS (SELECT 1 FROM historical_schema."character" ch WHERE ch.character_id = v.character_id::uuid)
  AND NOT EXISTS (SELECT 1 FROM historical_schema.context_character_mapping m WHERE m.mapping_id = v.mapping_id::uuid OR (m.context_id = v.context_id::uuid AND m.character_id = v.character_id::uuid))
ON CONFLICT DO NOTHING;

-- 9. Insert document_media_metadata_rows.sql
INSERT INTO historical_schema.document_media_metadata ("metadata_id", "document_id", "media_type", "file_format", "file_size_bytes", "width", "height", "storage_path", "thumbnail_path", "extended_metadata", "created_at", "updated_at", "entity_type", "entity_id")
