-- 10. Insert quiz_rows.sql
INSERT INTO historical_schema.quiz ("quiz_id", "title", "context_id", "created_by", "created_at", "updated_at", "deleted_at", "level", "is_published")
SELECT
    v.quiz_id::uuid,
    v.title,
    v.context_id::uuid,
    v.created_by::uuid,
    v.created_at::timestamp,
    v.updated_at::timestamp,
    v.deleted_at::timestamp,
    v.level,
    v.is_published::boolean
