à Trần lui quân về bãi sông Thiên Mạc để củng cố lực lượng và chuẩn bị phản công.', '2026-06-05 06:29:15.951702', '2026-06-05 06:29:15.951724', null), ('fbe85066-33ee-4e85-9719-d1dfd34b1f15', '9ac04e57-9043-42ac-a570-be5a2309615d', 'Tổng quân số phục vụ chiến dịch khi tính cả tuyến hậu cần được ước tính khoảng bao nhiêu người?', '["35.000","40.850","42.750","50.000"]', 2, 'Tài liệu nêu tổng quân số chiến dịch khoảng 42.750 người.', '2026-06-05 08:17:24.228229', '2026-06-05 08:17:24.228283', null), ('fd815e12-b606-4b4e-a566-9880ea85e2d2', '9323fbd1-8a75-4721-9f0c-738104e225ce', 'Ai là người chỉ huy cánh quân ở tả ngạn sông Bạch Đằng?', '["Đỗ Cảnh Thạc","Dương Tam Kha","Đào Nhuận","Ngô Xương Ngập"]', 2, 'Đào Nhuận được giao phối hợp cùng Dương Tam Kha chỉ huy các cánh quân mai phục ở hai bên bờ sông.', '2026-06-04 17:39:32.175167', '2026-06-06 09:58:47.303581', '2026-06-06 09:58:44.182127'), ('fe8f2de7-927b-40b2-9c13-e049be18025d', '546e4dcd-173a-4e7d-bae9-f63f20239a1d', 'Kẻ thù bị đánh bại trong trận Chi Lăng - Xương Giang là quân nào?', '["Nguyên Mông","Thanh","Minh","Tống"]', 2, 'Trận đánh nhằm tiêu diệt đạo viện binh nhà Minh sang cứu viện Đông Quan.', '2026-06-05 07:13:03.391436', '2026-06-05 07:13:03.391461', null), ('ff3810ae-c011-4c64-b0c6-70d2f55c29e9', 'c1cdd03f-42a1-41f0-9715-664420be546c', 'Độ chênh lệch giữa mức triều cao nhất và thấp nhất trong ngày quyết chiến là bao nhiêu?', '["1,2m","1,8m","2,3m","3,2m"]', 2, 'Mực nước cao nhất 3,20m và thấp nhất 0,90m, chênh lệch 2,30m.', '2026-06-05 07:11:41.600861', '2026-06-05 07:11:41.600883', null)
) AS v(question_id, quiz_id, content, options, correct_answer, explanation, created_at, updated_at, deleted_at)
WHERE EXISTS (SELECT 1 FROM historical_schema.quiz q WHERE q.quiz_id = v.quiz_id::uuid)
