-- 12. Insert daily_quest_rows.sql
INSERT INTO historical_schema.daily_quest ("quest_id", "type", "title", "target", "reward_tokens", "order_index", "is_active")
SELECT
    v.quest_id,
    v.type,
    v.title,
    v.target::integer,
    v.reward_tokens::integer,
    v.order_index::integer,
    v.is_active::boolean
FROM (VALUES
('chat_once', 'CHAT', 'Trò chuyện với một nhân vật lịch sử', 1, 500, 1, true), ('quiz_once', 'QUIZ', 'Hoàn thành 1 bài trắc nghiệm lịch sử', 1, 500, 2, true), ('read_context_once', 'READ_CONTEXT', 'Khám phá 1 bối cảnh lịch sử', 1, 300, 3, true)
) AS v(quest_id, type, title, target, reward_tokens, order_index, is_active)
WHERE NOT EXISTS (SELECT 1 FROM historical_schema.daily_quest dq WHERE dq.quest_id = v.quest_id)
ON CONFLICT DO NOTHING;

-- 13. Insert user_quest_progress_rows.sql
INSERT INTO historical_schema.user_quest_progress ("id", "user_uid", "date", "quest_id", "progress", "completed", "claimed")
SELECT
    v.id::uuid,
    v.user_uid::uuid,
    v.date::date,
    v.quest_id,
    v.progress::integer,
    v.completed::boolean,
    v.claimed::boolean
FROM (VALUES
('6db66028-83a1-4113-855d-ce208857c6a5', '3f27d018-3777-419a-acf0-c2cee4d23437', '2026-09-11', 'chat_once', 2, true, false)
) AS v(id, user_uid, date, quest_id, progress, completed, claimed)
WHERE EXISTS (SELECT 1 FROM historical_schema."user" u WHERE u.uid = v.user_uid::uuid)
  AND NOT EXISTS (SELECT 1 FROM historical_schema.user_quest_progress uqp WHERE uqp.id = v.id::uuid)
ON CONFLICT DO NOTHING;

